/// <summary>
///     The <c>AVACustConfirmTransDbt_Extension</c> class is the extension for <c>CustConfirmTrans</c>
/// </summary>
[ExtensionOf(tableStr(CustConfirmTrans))]
final class AVACustConfirmTransDbt_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>initFromSalesLine</c> method.
/// </summary>
/// <param name="_salesLine">
///    <c>SalesLine</c> as type
/// </param>
void initFromSalesLine(SalesLine _salesLine)
{
    #xppTexts
    InventTable avaInventTable = _salesLine.inventTable();
    EcoResProductTranslation    avaProductTranslation   = EcoResProductTranslation::findByProductLanguage(avaInventTable.Product, _salesLine.salesTable().LanguageId);
    SalesLine                   avaSalesLine_IC         = _salesLine.interCompanySalesLine();

    next initFromSalesLine(_salesLine);

    this.AVADlvMode                     = _salesLine.DlvMode;
    this.AVAIntrastatCommodity          = _salesLine.IntrastatCommodity;
    this.AVAPriceSurchargeCode          = _salesLine.AVAPriceSurchargeCode;
    this.AVAPriceSurchargePercentage    = _salesLine.AVAPriceSurchargePercentage;
    this.AVAQtyReserved                 = _salesLine.avaGetInventTransQtyReserved();
    this.AVAQuotationId                 = _salesLine.AVAQuotationId;
    this.AVAReceiptDateConfirmed        = _salesLine.ReceiptDateConfirmed;
    this.AVARemainInventPhysical        = _salesLine.RemainInventPhysical;
    this.AVAShippingDateConfirmed       = _salesLine.ShippingDateConfirmed;
    this.AVAPreferenceAuthorized        = _salesLine.NDX_PreferenceAuthorized;

    if(avaProductTranslation)
    {
        this.Name                       = avaProductTranslation.NDXProductName1 + #newLine + avaProductTranslation.NDXProductName2;
    }

    if(_salesLine.salesTable().NDX_ItemNameVersionReport == NDX_ItemNameVersionReport::LongText
        || _salesLine.AVAOverwriteText)
    {
        this.AVADescription                       += _salesLine.Name;
    }

    if(avaSalesLine_IC)
    {
        changecompany(_salesLine.salesTable().referencePurchTable().InterCompanyCompanyId)
        {
            this.AVAInventSiteId = avaSalesLine_IC.inventDim().InventSiteId;
        }
    }
    else
    {
        this.AVAInventSiteId = _salesLine.inventDim().InventSiteId;
    }

}
